function httpBody(response) {
  const status = response.statusCode;
  if (status === 401 || status === 403) throw new Error('CU28_AUTHORIZATION_REQUIRED');
  if (!Number.isInteger(status) || status < 200 || status >= 300) throw new Error('CU28_HTTP_UNAVAILABLE');
  if (!response.body || typeof response.body !== 'object' || Array.isArray(response.body)) {
    throw new Error('CU28_INVALID_RESPONSE');
  }
  return response.body;
}
try {httpBody($json);
const result = {status: 'owner_accepted', observedAt: new Date().toISOString()};
const state = $getWorkflowStaticData('global');
state.lastResult = result;
return [{json: result}];} catch (failure) {
const failureCode = /^CU28_[A-Z_]+$/.test(failure.message) ? failure.message : 'CU28_INTERNAL_FAILURE';
throw new Error(failureCode);
}

try {const allowed = ['CU28_INVALID_PERIOD', 'CU28_AUTHORIZATION_REQUIRED', 'CU28_HTTP_UNAVAILABLE',
